head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "1111",
        "col2": "aaaa",
        "col3": "가가가가",
        "col4": "123"
    }, {
        "col1": "1111",
        "col2": "aaaa",
        "col3": "가가가가",
        "col4": "234"
    }, {
        "col1": "1111",
        "col2": "aaaa",
        "col3": "가가가가",
        "col4": "34"
    }, {
        "col1": "2222",
        "col2": "bbb",
        "col3": "가가가가",
        "col4": "546"
    }, {
        "col1": "2222",
        "col2": "bbb",
        "col3": "가가가가",
        "col4": "73"
    }, {
        "col1": "2222",
        "col2": "bbb",
        "col3": "가가가가",
        "col4": "732"
    }, {
        "col1": "333",
        "col2": "ccc",
        "col3": "가가가가",
        "col4": "we"
    }, {
        "col1": "333",
        "col2": "ccc",
        "col3": "가가가가",
        "col4": "1234"
    }, {
        "col1": "333",
        "col2": "ccc",
        "col3": "가가가가",
        "col4": "09"
    }, {
        "col1": "1111",
        "col2": "aaaa",
        "col3": "가가가가",
        "col4": "091"
    }, {
        "col1": "1111",
        "col2": "aaaa",
        "col3": "가가가가",
        "col4": "029"
    }];
    dataList1.setJSON(jsonData);
    var rowJSON = dataList1.getRowJSON(0);
    var j = [];
    for (var i = 0; i < 150; i++) {
        var tmp = {};
        for (var item in rowJSON) {
            if (item == "rowStatus") continue;
            if (item == "col1") tmp[item] = item + "_" + Math.floor(i / 3);
            if (item == "col2") tmp[item] = "a" + Math.floor(i / 3);
            if (item == "col3") tmp[item] = "가가가가";
            if (item == "col4") tmp[item] = (i + 1);
            if (item == "col5") tmp[item] = "나나나나" + (i + 1);
            if (item == "col6") tmp[item] = "d" + (i + 1);
            if (item == "col8" && ((i % 3) == 0 || (i % 5) == 0)) tmp[item] = "1";
        }
        j.push(tmp);
    }
    dataList1.setJSON(j);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    /*
    var mergeInfo = {

    }; 
    gridView2.mergeCell( mergeInfo );
    */
    var all = dataList1.getAllJSON();
    console.log("before all: ", all);
    dataList1.setBroadcast(false);
    for (var i = 0; i < dataList1.getTotalRow(); i++) {
        var iopRecp = "[" + dataList1.getCellData(i, "col1") + "] " + dataList1.getCellData(i, "col3") + "-" + dataList1.getCellData(i, "col2");
        //dataList1.setCellData( i , "col5" , iopRecp ); //[입외]영수번호 form 만들기
        all[i]["col5"] = iopRecp;
        var cardTypeFm = "[" + dataList1.getCellData(i, "col1") + "] " + dataList1.getCellData(i, "col2");
        //dataList1.setCellData( i , "col6" , cardTypeFm ); //[미수구분]카드타입 form 만들기
        all[i]["col6"] = cardTypeFm;
        var uncTypeFm = dataList1.getCellData(i, "col1") + "/" + dataList1.getCellData(i, "col3") + " [" + dataList1.getCellData(i, "col4") + "]";
        //dataList1.setCellData( i , "col7" , uncTypeFm );
        all[i]["col7"] = uncTypeFm;
    }
    console.log("after all: ", all);
    dataList1.setJSON(all);
    dataList1.setBroadcast(true, true);
    for (var i = 0; i < dataList1.getTotalRow(); i++) {
        var unclMdf = dataList1.getCellData(i, "col8");
        if (unclMdf != "" && unclMdf == "1") { //미수변경=='1'일 때
            gridView2.setCellColor(i, "col6", "#186bb6");
            var mergeInfo = {
                rowIndex: i,
                rowSpan: 1,
                colIndex: 0,
                colSpan: 4,
                noDraw: true
            };
            gridView2.mergeCell(mergeInfo); //접수일자, 유형, 영수번호 셀 병합
        }
    }
};
scwin.trigger2_onclick = function(e) {
    gridView2.mergeClear();
};
